// MarkEntitiesOfTypeInvalid for edges, including its `invalid <> flag`
// guard and the reason for it: without that clause every schema edit
// would touch each of the type's edges and the set_updated_at trigger
// would move their updated_at, so a validation pass would read as an
// edit of content nobody edited.
//
// **It deliberately does not move `version`.** A sweep is not an edit by
// a caller: it changes no field an agent wrote, and bumping the version
// would refuse the very next `expected_version` an agent is holding --
// for a row whose values it never touched, over a schema edit made by
// somebody else. Flagging is a verdict about a row, not a new revision of
// it. MarkEntitiesOfTypeInvalid leaves entities' version alone for the
// same reason, and the two must stay the same on this point.
func (q *Queries) MarkRelationsOfTypeInvalid(ctx context.Context, arg MarkRelationsOfTypeInvalidParams) error {
	_, err := q.db.Exec(ctx, markRelationsOfTypeInvalid,
		arg.Invalid,
		arg.ProjectID,
		arg.RelationTypeID,
		arg.Ids,
	)
	return err
}

const pruneEntityTypeFromEndpointLists = `-- name: PruneEntityTypeFromEndpointLists :many
UPDATE relation_types
SET source_type_ids = array_remove(source_type_ids, $1::uuid),
    target_type_ids = array_remove(target_type_ids, $1::uuid)
WHERE project_id = $2::uuid
  AND $1::uuid = ANY (source_type_ids || target_type_ids)
RETURNING id, key
`

type PruneEntityTypeFromEndpointListsParams struct {
	EntityTypeID uuid.UUID
	ProjectID    uuid.UUID
}

type PruneEntityTypeFromEndpointListsRow struct {
	ID  uuid.UUID
	Key string
}

// Removes a deleted entity type's id from every relation type's endpoint
// lists. source_type_ids and target_type_ids are plain uuid[]: Postgres
// has no foreign key from an array element, so nothing but this
// statement keeps them from outliving the type they name. It runs in the
// same transaction as the type's own delete.
//
// It returns the identity of every row it changed, because the caller
// announces them: this is a write to relation types nobody named, and a
// subscriber has no other way to learn its copy of an endpoint rule is
// stale. An UPDATE cannot order its RETURNING, so the caller sorts what
// comes back before announcing it: an unordered burst is a burst that
// arrives differently twice.
func (q *Queries) PruneEntityTypeFromEndpointLists(ctx context.Context, arg PruneEntityTypeFromEndpointListsParams) ([]PruneEntityTypeFromEndpointListsRow, error) {
	rows, err := q.db.Query(ctx, pruneEntityTypeFromEndpointLists, arg.EntityTypeID, arg.ProjectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PruneEntityTypeFromEndpointListsRow
	for rows.Next() {
		var i PruneEntityTypeFromEndpointListsRow
		if err := rows.Scan(&i.ID, &i.Key); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchEntities = `-- name: SearchEntities :many
SELECT e.id, e.project_id, e.entity_type_id, e.key, e.name, e.fields, e.invalid, e.version, e.search, e.created_at, e.updated_at, e.updated_by_user_id, e.updated_by_token_id,
       ts_rank(e.search, plainto_tsquery('simple', $1::text)) AS rank,
       (ts_filter(e.search, '{a}') @@ plainto_tsquery('simple', $1::text))::bool AS name_match
FROM entities e
WHERE e.project_id = $2::uuid
  AND ($3::uuid IS NULL OR e.entity_type_id = $3::uuid)
  AND e.search @@ plainto_tsquery('simple', $1::text)
ORDER BY name_match DESC, rank DESC, e.name, e.id
LIMIT $4::int
`

type SearchEntitiesParams struct {
	Query        string
	ProjectID    uuid.UUID
	EntityTypeID *uuid.UUID
	Limit        int32
}

type SearchEntitiesRow struct {
	ID               uuid.UUID
	ProjectID        uuid.UUID
	EntityTypeID     uuid.UUID
	Key              string
	Name             string
	Fields           []byte
	Invalid          bool
	Version          int32
	Search           pgtype.TSVector
	CreatedAt        pgtype.Timestamptz
	UpdatedAt        pgtype.Timestamptz
	UpdatedByUserID  *uuid.UUID
	UpdatedByTokenID *uuid.UUID
	Rank             float32
	NameMatch        bool
}

// Full-text search over a game's entities, ranked.
//
// The project filter is load-bearing: the query text is the caller's and
// names no parent, so nothing but this clause keeps a search inside one
// game.
//
// ORDER BY carries id after name for the reason ListEntityTypes records:
// neither rank nor name is unique, and an order that can tie reshuffles
// its ties between two identical calls.
//
// **name_match leads the ordering, and it is what makes the ranking
// promise true rather than usually true — review finding M1.** The
// promise the tool description and Search's doc comment both make is
// that a row the query *names* outranks a row that only mentions the
// words in a field, however often it mentions them. Weights alone do
// not deliver that. `ts_rank` saturates towards 1.0 as a lexeme
// repeats, so for a single word the A weight wins comfortably, but for
// a multi-word query the weighted sum of several saturating terms
// overtakes it: four repetitions of a two-word phrase in a lore field
// were enough to beat the entity actually named that phrase. An
// explicit weight array only moves the number of repetitions it takes,
// because the shape of the curve is the problem and not its scale.
//
// `ts_filter(e.search, '{a}')` keeps only the A-weighted lexemes, which
// 0006_weighted_entity_search.sql and UpsertEntity both build from the
// row's name and nothing else, so this predicate asks exactly the
// question the promise is about: does the *name* satisfy the query. As
// a leading sort key it is a guarantee rather than a tendency — no
// amount of repetition in a field can lift a row past one whose name
// matches — and `rank` still orders within each of the two groups, so
// the weights keep doing the work they were introduced for.
//
// After 0006's Down arm `strip` has removed every weight, so this
// predicate is uniformly false and the ordering falls back to rank
// alone. That is the same degradation that migration already documents
// for a downgraded database: search works, it just ranks the old way
// until its rows are rewritten.
//
// The tsquery is built three times, not twice — once in the rank
// projection, once in the name_match projection (added for review
// finding M1) and once in the WHERE — because a WHERE cannot refer to an
// output column's alias and the two projections answer different
// questions (name_match filters to the A weight first, rank does not).
//
// **On the call path this statement actually takes, that costs nothing
// to run, and this comment used to claim otherwise for the wrong case.**
// The prior text measured a *non-constant* plainto_tsquery — the query
// text spliced into the SQL itself rather than bound as a parameter —
// and found no folding there: 0.63 ms once against 1.44 ms written
// twice at 4 KiB. That is not this statement's path. sqlc's generated
// caller and every production caller reach Postgres through pgx's
// extended protocol: `query` arrives as bound parameter $1, and
// `plainto_tsquery` is declared IMMUTABLE, so once the parameter value
// is known at plan time every occurrence collapses to the identical
// `::tsquery` literal. `EXPLAIN (ANALYZE, VERBOSE)` on this project's
// own Postgres, real seeded rows, the same bound-parameter path
// dbq.SearchEntities uses, shows exactly that: for query text "gnoll
// pack", all three occurrences of plainto_tsquery print in the plan as
// the identical ::tsquery literal (Postgres's own doubled-quote spelling
// of the two lexemes), not as a repeated function call.
// Timed end to end over 200 runs through the same pool.Query path: the
// statement as written (three occurrences) and a hand-rewritten version
// built once via a LATERAL join and referenced three times measured
// 0.370 ms and 0.389 ms per run respectively — indistinguishable, and
// if anything the "once" form was the slower one, which is what
// constant folding predicts: there is nothing left to save by writing
// it once.
//
// So it stays written three times for the same reason it stayed written
// twice before: doing that by hand — a
// `WITH q AS MATERIALIZED (SELECT plainto_tsquery(...) AS ts)` joined
// in — was measured too, and it is worse, not neutral. It blocks the
// planner from seeing the tsquery as a constant, and the row estimate
// for the match went from 5 (exact) to 100 (a default guess) on the
// same data. Trading a correct selectivity estimate on every search for
// a folding the planner already does for free is the wrong way round.
//
// **This is scoped to the path pgx's extended protocol takes.** A caller
// that interpolates the query text into the SQL string instead of
// binding it as a parameter loses the constant the planner is folding
// on, and lands back in the non-constant case the superseded measurement
// above describes. Nothing in this package does that; if a future
// caller ever does, re-measure rather than trust either number here.
func (q *Queries) SearchEntities(ctx context.Context, arg SearchEntitiesParams) ([]SearchEntitiesRow, error) {
	rows, err := q.db.Query(ctx, searchEntities,
		arg.Query,
		arg.ProjectID,
		arg.EntityTypeID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchEntitiesRow
	for rows.Next() {
		var i SearchEntitiesRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.EntityTypeID,
			&i.Key,
			&i.Name,
			&i.Fields,
			&i.Invalid,
			&i.Version,
			&i.Search,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.UpdatedByUserID,
			&i.UpdatedByTokenID,
			&i.Rank,
			&i.NameMatch,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertEntity = `-- name: UpsertEntity :one
INSERT INTO entities (project_id, entity_type_id, key, name, fields, search,
                      updated_by_user_id, updated_by_token_id)
VALUES ($1::uuid, $2::uuid,
        $3::text, $4::text, $5::jsonb,
        setweight(to_tsvector('simple', $4::text), 'A')
          || setweight(to_tsvector('simple', $4::text || ' ' || $6::text), 'B'),
        $7::uuid, $8::uuid)
ON CONFLICT (project_id, entity_type_id, lower(key)) DO UPDATE
SET name                = excluded.name,
    fields              = excluded.fields,
    search              = excluded.search,
    invalid             = false,
    version             = entities.version + 1,
    updated_by_user_id  = excluded.updated_by_user_id,
    updated_by_token_id = excluded.updated_by_token_id
WHERE entities.version = $9::integer
RETURNING id, project_id, entity_type_id, key, name, fields, invalid, version, search, created_at, updated_at, updated_by_user_id, updated_by_token_id
`

type UpsertEntityParams struct {
	ProjectID        uuid.UUID
	EntityTypeID     uuid.UUID
	Key              string
	Name             string
	Fields           []byte
	SearchText       string
	UpdatedByUserID  *uuid.UUID
	UpdatedByTokenID *uuid.UUID
	ExpectedVersion  int32
}

// The same shape as UpsertEntityType, for the same reasons, and that
// statement's comment carries the full argument. In short:
//
//   - The DO UPDATE is guarded by the caller's expected version, so the
//     whole compare-and-set is one statement and two writers cannot both
//     read version 1 and both succeed. A creating caller passes
//     noVersion, which no stored version can equal.
//   - The key column is deliberately not in the SET list. The first
//     spelling stored stands, and the returned row therefore still
//     carries it -- which is what lets Go refuse a respelling *after* the
//     write, closing the creation-race hole.
//   - No write sets updated_at: 0004_metamodel.sql puts a set_updated_at
//     trigger on all four tables, and a clause here would be a second
//     mechanism behind one column.
//   - The audit columns are carried, so the composite
//     FOREIGN KEY (updated_by_token_id, project_id) catches a token
//     scoped to another game.
//
// search is written by this statement and by nothing else, on both arms
// of the upsert. **It is weighted**: the name goes in twice, once alone
// under label A and once as the head of the whole text under label B.
// The A half is what SearchEntities' leading sort key reads to put a row
// the query names above a row that merely mentions the words — see its
// own comment for why that is a sort key and not a weight — and the
// weights order the rows within each of those two groups.
// 0006_weighted_entity_search.sql records why the B
// half carries the name rather than the fields alone — it is what makes
// that migration's backfill an exact function of the vector this
// statement used to write, so a migrated row and a re-seeded row rank
// the same. It cannot be a generated column: it is derived from
// user-declared jsonb whose *text* fields are the only ones worth
// indexing, and which of a row's fields those are is known only to the
// Go validator that has just read the type's schema. So every write path
// that changes name or fields must come through here, or the row stays
// indexed under its previous words and a search stops finding it with
// nothing to signal why.
//
// invalid is reset to false because the caller has just validated these
// values against the type's current schema; a row that is being written
// is a row that has been judged.
func (q *Queries) UpsertEntity(ctx context.Context, arg UpsertEntityParams) (Entity, error) {
	row := q.db.QueryRow(ctx, upsertEntity,
		arg.ProjectID,
		arg.EntityTypeID,
		arg.Key,
		arg.Name,
		arg.Fields,
		arg.SearchText,
		arg.UpdatedByUserID,
		arg.UpdatedByTokenID,
		arg.ExpectedVersion,
	)
	var i Entity
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.EntityTypeID,
		&i.Key,
		&i.Name,
		&i.Fields,
		&i.Invalid,
		&i.Version,
		&i.Search,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedByUserID,
		&i.UpdatedByTokenID,
	)
	return i, err
}

const upsertEntityType = `-- name: UpsertEntityType :one
INSERT INTO entity_types (project_id, key, label, label_plural, description, color, icon,
                          field_schema, updated_by_user_id, updated_by_token_id)
VALUES ($1::uuid, $2::text, $3::text,
        $4::text, $5::text,
        $6::text, $7::text, $8::jsonb,
        $9::uuid, $10::uuid)
ON CONFLICT (project_id, lower(key)) DO UPDATE
SET label               = excluded.label,
    label_plural        = excluded.label_plural,
    description         = excluded.description,
    color               = excluded.color,
    icon                = excluded.icon,
    field_schema        = excluded.field_schema,
    version             = entity_types.version + 1,
    updated_by_user_id  = excluded.updated_by_user_id,
    updated_by_token_id = excluded.updated_by_token_id
WHERE entity_types.version = $11::integer
RETURNING id, project_id, key, label, label_plural, description, color, icon, field_schema, version, created_at, updated_at, updated_by_user_id, updated_by_token_id
`

type UpsertEntityTypeParams struct {
	ProjectID        uuid.UUID
	Key              string
	Label            string
	LabelPlural      string
	Description      string
	Color            string
	Icon             string
	FieldSchema      []byte
	UpdatedByUserID  *uuid.UUID
	UpdatedByTokenID *uuid.UUID
	ExpectedVersion  int32
}

// Every statement in this file carries the resolved project id -- the
// reads and deletes as a filter, including the ones addressing a row by
// its primary key, and the upserts as the column they write. Isolation
// between games is enforced in SQL, not in Go, so a query trusting an id
// alone would hand a caller another game's row the moment an id leaked.
//
// That is the whole mechanism only for the statements addressing a row
// by its own primary key: GetEntityTypeByID and DeleteEntityType, which
// TestTypesAreScopedToTheirProject pins, and GetEntityByID and
// DeleteEntity, which
// TestTheEntityQueriesThatAddressARowByIDAreScopedToTheProject pins.
// Drop the filter from any of the four and a leaked id reads, or
// deletes, another game's row. The entity pair needed a test of its own
// against the queries: their only caller is RemoveEntity, which reads
// the row, then its type, then deletes, so each of its three filters
// masks the others and only mutating all three at once is observable
// through the service.
//
// It is *not* the mechanism for the statements reaching entities through
// an entity_type_id (ListEntityFieldsOfType, MarkEntitiesOfTypeInvalid,
// DeleteEntitiesOfType, GetEntityByKey, GetEntityByKeyForUpdate).
// 0004_metamodel.sql gives entities a composite
// FOREIGN KEY (entity_type_id, project_id) REFERENCES
// entity_types (id, project_id), so an entity's project is already
// determined by its type's: no row can match a type id under one project
// id and not another, and dropping the filter from any of those five
// changes no result and can be caught by no test. They keep it as
// defence in depth, against a future schema that relaxes that composite
// key, and so that a
// reader adding the next entities query copies the safe shape rather than
// having to work out which statements happen to be covered by a
// constraint. Written down here because a comment claiming these filters
// are what isolates games would be relied on as if it were true.
//
// UpsertEntity is deliberately not in that list, and is not unobservable
// either: it has no project filter at all. Its project_id is a NOT NULL
// column value it writes and part of its ON CONFLICT
// (project_id, entity_type_id, lower(key)) target, so removing it is a
// syntax or constraint error rather than a silently widened query --
// nothing about it can be dropped and still compile.
//
// No write here sets updated_at. 0004_metamodel.sql puts a set_updated_at
// trigger on all four tables, so the column has one mechanism behind it
// rather than a trigger plus a clause every future query must remember.
//
// The DO UPDATE is guarded by the caller's expected version, so the whole
// compare-and-set happens in one statement and two concurrent writers
// cannot both read version 1 and both succeed. A creating caller has no
// version to expect and passes noVersion, which no stored version can
// equal, so the guard is a no-op on the insert path and a guaranteed
// mismatch when a row it did not know about turns out to exist. A guard
// that fails returns no row rather than an error; UpsertEntityType turns
// that into the typed conflict.
//
// Idempotent by (project, key), matched case-insensitively through the
// entity_types_key_key index. The key column itself is deliberately not in
// the SET list: the first spelling stored stays, so a re-seed cannot
// rewrite the handle other rows and documents refer to. That omission is
// also what lets UpsertEntityType in Go refuse a respelling *after* this
// statement runs: the row returned still carries the stored key, so
// comparing it to the submitted one catches a writer whose own locked read
// could not have seen this row at all — a creation racing a creator, where
// there was nothing yet to lock. So this clause is what makes an identical
// spelling a no-op; it is not what resolves a conflict.
func (q *Queries) UpsertEntityType(ctx context.Context, arg UpsertEntityTypeParams) (EntityType, error) {
	row := q.db.QueryRow(ctx, upsertEntityType,
		arg.ProjectID,
		arg.Key,
		arg.Label,
		arg.LabelPlural,
		arg.Description,
		arg.Color,
		arg.Icon,
		arg.FieldSchema,
		arg.UpdatedByUserID,
		arg.UpdatedByTokenID,
		arg.ExpectedVersion,
	)
	var i EntityType
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Key,
		&i.Label,
		&i.LabelPlural,
		&i.Description,
		&i.Color,
		&i.Icon,
		&i.FieldSchema,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedByUserID,
		&i.UpdatedByTokenID,
	)
	return i, err
}

const upsertRelation = `-- name: UpsertRelation :one
INSERT INTO relations (project_id, relation_type_id, source_id, target_id, fields,
                       updated_by_user_id, updated_by_token_id)
VALUES ($1::uuid, $2::uuid,
        $3::uuid, $4::uuid, $5::jsonb,
        $6::uuid, $7::uuid)
ON CONFLICT (relation_type_id, source_id, target_id) DO UPDATE
SET fields              = excluded.fields,
    invalid             = false,
    version             = relations.version + 1,
    updated_by_user_id  = excluded.updated_by_user_id,
    updated_by_token_id = excluded.updated_by_token_id
WHERE relations.project_id = excluded.project_id
  AND relations.version = $8::integer
RETURNING id, project_id, relation_type_id, source_id, target_id, fields, created_at, updated_at, updated_by_user_id, updated_by_token_id, invalid, version
`

type UpsertRelationParams struct {
	ProjectID        uuid.UUID
	RelationTypeID   uuid.UUID
	SourceID         uuid.UUID
	TargetID         uuid.UUID
	Fields           []byte
	UpdatedByUserID  *uuid.UUID
	UpdatedByTokenID *uuid.UUID
	ExpectedVersion  int32
}

// **The DO UPDATE is guarded by the caller's expected version**, exactly
// as UpsertEntity's and UpsertEntityType's are, so the whole
// compare-and-set is one statement and two writers cannot both read
// version 1 and both succeed. A creating caller passes noVersion, which
// no stored version can equal, so the guard is a no-op on the insert path
// and a guaranteed mismatch when a row it did not know about turns out to
// exist. A guard that fails returns no row rather than an error;
// UpsertRelation turns that into the typed conflict.
//
// Until 0009 this statement had no guard at all and said so: an edge was
// last-writer-wins, and two designers extending one edge's `passages`
// list at the same time silently lost one of the two. That was the
// documented behaviour of the one table in this schema without a
// version, and 0009 records why it could not stay.
//
// **invalid is reset to false on both arms**, for the reason UpsertEntity
// resets it: the caller has just validated these values against the
// relation type's current schema, and a row that is being written is a
// row that has been judged. An edge that had been flagged by a sweep
// therefore stops being flagged the moment it is rewritten to fit -- and
// if it does not fit, the write never reaches this statement.
//
// The ON CONFLICT target is relations_edge_key, so a re-seed of the same
// edge updates it rather than laying a second copy beside it. That is
// also why a game cannot hold two edges of one type between one ordered
// pair; UpsertRelation's doc comment says what to do when it genuinely
// needs to.
//
// No updated_at either -- the set_updated_at trigger owns that column on
// all four tables. project_id is the column this statement writes rather
// than a filter it applies, exactly as in UpsertEntity.
//
// **The isolation takes two mechanisms, and the composite keys are only
// the first.** On the insert path there is nothing to filter: the
// composite foreign keys on the type and on both endpoints have no
// matching row for a parent from another game and the write raises
// 23503. On the **conflict** path they check nothing at all. The
// conflict target is (relation_type_id, source_id, target_id), which
// names no project, and project_id is not in the SET list -- so the
// stored row keeps its own project id, every key stays satisfied, and
// the DO UPDATE is an update of another game's edge that then RETURNs
// that game's whole row. Measured, not reasoned about: one game calling
// with its own project id and another game's three ids overwrote that
// game's fields and was handed back a row carrying the other game's
// project id -- a cross-game write and a cross-game read in one
// statement.
//
// So the load-bearing filter on this path is the DO UPDATE's own
// WHERE relations.project_id = excluded.project_id, and it is the only
// thing here that carries the project through the conflict; the
// composite keys cannot, because they constrain what a row may *hold*,
// not which rows an ON CONFLICT may *match*. A guard that matches
// nothing updates nothing, so the statement returns no row and Go sees
// pgx.ErrNoRows instead of a silent success.
//
// Unreachable from Service.UpsertRelation, which resolves the type and
// both endpoints by key inside the project before it gets here, and kept
// anyway for the reason internal/views' position write keeps its twin: a
// statement that is safe only because of how today's caller happens to
// address it is a trap for tomorrow's caller.
// TestUpsertRelationsConflictPathCannotWriteAnotherGamesEdge drives the
// statement directly, which is the only way to observe a filter every
// service path has already made redundant.
func (q *Queries) UpsertRelation(ctx context.Context, arg UpsertRelationParams) (Relation, error) {
	row := q.db.QueryRow(ctx, upsertRelation,
		arg.ProjectID,
		arg.RelationTypeID,
		arg.SourceID,
		arg.TargetID,
		arg.Fields,
		arg.UpdatedByUserID,
		arg.UpdatedByTokenID,
		arg.ExpectedVersion,
	)
	var i Relation
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.RelationTypeID,
		&i.SourceID,
		&i.TargetID,
		&i.Fields,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedByUserID,
		&i.UpdatedByTokenID,
		&i.Invalid,
		&i.Version,
	)
	return i, err
}

const upsertRelationType = `-- name: UpsertRelationType :one
INSERT INTO relation_types (project_id, key, label, description,
                            source_type_ids, target_type_ids, semantic_role, field_schema,
                            updated_by_user_id, updated_by_token_id)
VALUES ($1::uuid, $2::text, $3::text,
        $4::text, $5::uuid[],
        $6::uuid[], $7::text,
        $8::jsonb,
        $9::uuid, $10::uuid)
ON CONFLICT (project_id, lower(key)) DO UPDATE
SET label               = excluded.label,
    description         = excluded.description,
    source_type_ids     = excluded.source_type_ids,
    target_type_ids     = excluded.target_type_ids,
    semantic_role       = excluded.semantic_role,
    field_schema        = excluded.field_schema,
    version             = relation_types.version + 1,
    updated_by_user_id  = excluded.updated_by_user_id,
    updated_by_token_id = excluded.updated_by_token_id
WHERE relation_types.version = $11::integer
RETURNING id, project_id, key, label, description, source_type_ids, target_type_ids, semantic_role, field_schema, version, created_at, updated_at, updated_by_user_id, updated_by_token_id
`

type UpsertRelationTypeParams struct {
	ProjectID        uuid.UUID
	Key              string
	Label            string
	Description      string
	SourceTypeIds    []uuid.UUID
	TargetTypeIds    []uuid.UUID
	SemanticRole     *string
	FieldSchema      []byte
	UpdatedByUserID  *uuid.UUID
	UpdatedByTokenID *uuid.UUID
	ExpectedVersion  int32
}

// Guarded, audited and trigger-owned exactly as UpsertEntityType is; see
// that statement's comment for the full argument. In short: the DO UPDATE
// carries the caller's expected version so the compare-and-set is one
// statement, no write sets updated_at because the set_updated_at trigger
// owns it, and key is not in the SET list, so the stored spelling stands
// and the returned row is what lets Go refuse a respelling after the
// write.
func (q *Queries) UpsertRelationType(ctx context.Context, arg UpsertRelationTypeParams) (RelationType, error) {
	row := q.db.QueryRow(ctx, upsertRelationType,
		arg.ProjectID,
		arg.Key,
		arg.Label,
		arg.Description,
		arg.SourceTypeIds,
		arg.TargetTypeIds,
		arg.SemanticRole,
		arg.FieldSchema,
		arg.UpdatedByUserID,
		arg.UpdatedByTokenID,
		arg.ExpectedVersion,
	)
	var i RelationType
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Key,
		&i.Label,
		&i.Description,
		&i.SourceTypeIds,
		&i.TargetTypeIds,
		&i.SemanticRole,
		&i.FieldSchema,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedByUserID,
		&i.UpdatedByTokenID,
	)
	return i, err
}
